pub(super) fn publish_with_readback<'db>(
    db: &'db Connection,
    settings: &'db Settings,
    parent: Hash,
    block: Hash,
    before: &State,
    after: &State,
    progress: &mut dyn FnMut() -> Result<()>,
    cache: Option<&ArithmeticCache>,
