        &self.settings.app,
    )
    .map_err(|error| Error::from(error).local_integrity())?;
    let prior = self.cached_parent(tip)?;
    progress()?;
    let prepared = self.checked_commitment(
        &state,
        self.record(tip).map_err(Error::local_integrity)?.root,
        prior.as_ref(),
    )?;
