fn state_at_with_readback(
    &self,
    tip: Hash,
    progress: &mut dyn FnMut() -> Result<()>,
    mut readback: Option<&mut native_authenticated::PostWriteReadback<'_>>,
) -> Result<State> {
    ensure(
        self.state_backend != StateBackend::PermanentAccountGrowthV2,
        "GROWTH_COMPLETE_STATE_UNAVAILABLE",
    )?;
    let _measurement = (self.state_backend == StateBackend::AuthenticatedV1).then(|| {
        self.authenticated_arithmetic
            .history
            .observe(native_authenticated::HistoryStage::StateAt)
    });
    progress()?;
    if tip == self.active()?.0 {
        return Ok(self.read_active_with_readback(progress, readback)?.2);
    }
    let mut path = reverse_path::ReversePath::new(tempfile::tempfile()?);
    let mut count = 0u64;
    let mut cur = tip;
    let (mut state, mut commitment): (State, Option<CheckedCommitment>) = loop {
        progress()?;
        let row = self.record(cur)?;
        let snapshot = self
            .db
            .prepare_cached("SELECT state FROM snapshots WHERE block=?")?
            .query_row([cur.as_slice()], |r| r.get::<_, Vec<u8>>(0))
            .optional()?;
        if let Some(bytes) = snapshot {
            let state: State = serde_json::from_slice(&bytes)
                .map_err(|error| Error::from(error).local_integrity())?;
            ensure(canonical(&state)? == bytes, "STATE_BYTES")
                .map_err(Error::local_integrity)?;
            continuity_v1::check_state(&state, row.height, &self.settings.app)
                .map_err(|error| Error::from(error).local_integrity())?;
            let commitment = self
                .checked_historical_commitment(cur, &state, row.root, None)?
                .snapshot;
            if self.state_backend == StateBackend::AuthenticatedV1 {
                native_authenticated::verify_state_with_readback(
                    &self.db,
                    &self.settings,
                    cur,
                    &state,
                    progress,
                    Some(&self.authenticated_arithmetic),
                    readback.as_deref_mut(),
                )?;
            }
            break (state, commitment);
        }
        path.push(cur)?;
        count = count.checked_add(1).ok_or("ANCESTRY_LIMIT")?;
        cur = self.parent(cur)?;
    };
    for _ in 0..count {
        progress()?;
        let id = path.pop()?.ok_or("ANCESTRY_LIMIT")?;
        for (index, (key, before, after)) in self
            .delta_rows_with_progress(id, progress)?
            .into_iter()
            .enumerate()
        {
            if index.is_multiple_of(256) {
                progress()?;
            }
            ensure(
                state.get(&key).map(canonical).transpose()? == before,
                "UNDO_ROOT",
            )
            .map_err(Error::local_integrity)?;
            if let Some(bytes) = after {
                state.insert(
                    key,
                    serde_json::from_slice(&bytes)
                        .map_err(|error| Error::from(error).local_integrity())?,
                );
            } else {
                state.remove(&key);
            }
        }
        commitment = self
            .checked_historical_commitment(
                id,
                &state,
                self.record(id)?.root,
                commitment.as_ref(),
            )?
            .snapshot;
        continuity_v1::check_state(&state, self.record(id)?.height, &self.settings.app)
            .map_err(|error| Error::from(error).local_integrity())?;
        if self.state_backend == StateBackend::AuthenticatedV1 {
            native_authenticated::verify_state_with_readback(
                &self.db,
                &self.settings,
                id,
                &state,
                progress,
                Some(&self.authenticated_arithmetic),
                readback.as_deref_mut(),
            )?;
        }
    }
    progress()?;
    if let Some(scope) = readback {
        scope.validate_consumed(&self.db)?;
    }
    Ok(state)
}

