    self.resume_intent(&mut None)?;
    let best: Vec<u8> = self.db.query_row(
        "SELECT id FROM blocks ORDER BY chainwork DESC,height,id LIMIT 1",
        [],
        |r| r.get(0),
    )?;
    self.activate(bytes32(best)?)
}
