/// A cold complete calculation may lend its freshly parsed accounts to the
/// immediate graph verifier. Exact-input cache hits return no projection:
/// only the commitment is retained, and the graph parses actual State anew.
pub(super) fn complete_with_current_accounts<'a>(
    &self,
    settings: &Settings,
    state: &'a State,
) -> Result<(StateCommitment, Option<CurrentAccounts<'a>>)> {
    let _measurement = self
        .history
        .observe(super::HistoryStage::CompleteCommitment);
    let context = [
        settings.network(),
        settings.parameters(),
        settings.genesis(),
    ];
    // Serialize actual complete input, not a caller's root or Value equality:
    // signed zero and integer/float representations must remain distinct.
    // Oversize input never retains a complete commitment verdict. Its full
    // account/conservation checks still run with bounded root arithmetic.
    let bytes = bounded_bytes(state);
    if let (Some(bytes), Ok(entries)) = (bytes.as_ref(), self.complete.try_borrow()) {
        if let Some(entry) = entries.iter().find(|entry| {
            entry.context == context && entry.bytes.as_slice() == bytes.as_slice()
        }) {
            self.root_arithmetic.complete_hit();
            #[cfg(test)]
            self.hits.set(self.hits.get() + 1);
            return Ok((entry.value.clone(), None));
        }
    }
    self.root_arithmetic.complete_computation();
    let (value, current_accounts) = commitment_from_complete_state_with_current_accounts(
        settings,
        state,
        Some(&self.lifts),
        || self.complete_root(settings, state, bytes.as_deref()),
        |partition| {
            self.root_arithmetic
                .calculate_non_accounts(settings, partition)
        },
    )
    .map_err(|error| {
        crate::Error::from(format!("NATIVE_STATE_COMMITMENT:{error:?}")).local_integrity()
    })?;
    if let (Some(bytes), Ok(mut entries)) = (bytes, self.complete.try_borrow_mut()) {
        if entries.len() == MAX_COMPLETE_ENTRIES {
            entries.pop_front();
        }
        entries.push_back(CompleteEntry {
            context,
            bytes,
            value: value.clone(),
        });

/// Return the account projection already needed by this complete calculation.
/// All original parsing, roots, aggregates, conservation and error order run
/// before it is returned. An immediate graph verifier can borrow these values
/// instead of parsing this unchanged State a second time.
pub(crate) fn commitment_from_complete_state_with_current_accounts<'a>(
    settings: &Settings,
    state: &'a State,
    lifts: Option<&crate::account_archive_prototype::native_store::LiftCache>,
    calculate_root: impl FnOnce() -> pon_executor::Result<Hash>,
    calculate_non_account_root: impl FnOnce(&State) -> pon_executor::Result<Hash>,
) -> Result<(StateCommitment, CurrentAccounts<'a>)> {
    let account_values = accounts(state)?;
    let commitment = commitment_with_non_account_root(
        Context {
            network: settings.network(),
            parameters: settings.parameters(),
            genesis: settings.genesis(),
        },
        relation(calculate_root())?,
        match lifts {
            Some(lifts) => {
                crate::account_archive_prototype::account_root_with_lifts(&account_values, lifts)?
            }
            None => crate::account_archive_prototype::account_root(&account_values)?,
        },
        account_values.len() as u64,
        total(account_values.values().map(|value| value.balance))?,
        &non_accounts(state),
        calculate_non_account_root,
    )?;
    Ok((
        commitment,
        CurrentAccounts {
            state,
            values: account_values,
        },
    ))
